import { readFileSync } from "node:fs";
import { join } from "node:path";
import { expect, test } from "vitest";
import { api } from "../convex/_generated/api";
import { createTestConvex } from "./testUtils";

/**
 * End-to-end physical inventory import (Phase 2 §3) against a REAL .xlsx
 * fixture (tests/fixtures/agc-room-inventory-integration.xlsx, generated by
 * scripts/make-room-fixture.mjs). The fixture mirrors the accommodation team's
 * own workbook: one sheet per type, a title row, then a NO. OF ROOMS / ROOM
 * NUMBER / CAPACITY header row with one room per row — no location column and
 * no gender column. Covers workbook parse → preview → import commit, including
 * the invalid-row report and the EBPV apartment rules (§7).
 */

const FIXTURE_PATH = join(process.cwd(), "tests", "fixtures", "agc-room-inventory-integration.xlsx");

type TestConvex = ReturnType<typeof createTestConvex>;

async function seedAdminAndPools(t: TestConvex) {
  const { createHash, randomBytes } = await import("node:crypto");
  const token = createHash("sha256").update(randomBytes(24)).digest("hex");
  await t.run(async (ctx) => {
    const now = Date.now();
    const userId = await ctx.db.insert("users", {
      name: "Room Admin",
      email: "roomadmin@example.com",
      passwordHash: "not-a-real-hash",
      role: "accommodation",
      active: true,
      createdAt: now,
    });
    await ctx.db.insert("sessions", {
      userId,
      token,
      expiresAt: now + 3_600_000,
      createdAt: now,
    });
    // Phase 1 corrected inventory pools the import may never exceed.
    const pools: Array<
      ["dormitory" | "hostel" | "wise_serpents" | "good_general" | "ebpv", number]
    > = [
      ["dormitory", 2500],
      ["hostel", 8],
      ["wise_serpents", 4],
      ["good_general", 2],
      ["ebpv", 8],
    ];
    for (const [accommodationType, total] of pools) {
      await ctx.db.insert("agcInventoryPools", {
        accommodationType,
        scope: "global",
        total,
        reserved: 0,
        confirmed: 0,
      });
    }
  });
  return { token };
}

test("real Excel fixture: parse, preview, and commit the physical inventory", async () => {
  const t = createTestConvex();
  const { token } = await seedAdminAndPools(t);
  const contentBase64 = readFileSync(FIXTURE_PATH).toString("base64");
  expect(contentBase64.length).toBeGreaterThan(1000); // a real workbook arrived

  // 1. Parse the workbook. Titles and cover sheets are skipped, the header row
  //    is found wherever it sits, and the type comes from the sheet/title.
  const parsed = await t.action(api.agcRoomsImport.parseRoomImportWorkbook, {
    sessionToken: token,
    contentBase64,
  });
  expect(parsed.rows).toHaveLength(7); // 2 hostel + 2 WASL + 1 GGL + 2 EBPV
  expect(parsed.invalidRows).toHaveLength(1);
  expect(parsed.invalidRows[0].row).toBe(5); // hostel 103 has no capacity
  expect(parsed.invalidRows[0].reason).toMatch(/capacity "" for 103/);

  // The "NO. OF ROOMS" counter column is ignored — room names come from the
  // ROOM NUMBER / Apartment name column only.
  const hostelNames = parsed.rows
    .filter((row) => row.accommodationType === "hostel")
    .map((row) => row.name);
  expect(hostelNames).toEqual(["101", "102"]);
  expect(parsed.rows.find((row) => row.name === "101")).toMatchObject({
    accommodationType: "hostel",
    capacity: 4,
  });
  expect(parsed.rows.find((row) => row.name === "101")?.building).toBeUndefined();

  // The extra WASL information column shifts capacity to the last column.
  const wasl = parsed.rows.filter((row) => row.accommodationType === "wise_serpents");
  expect(wasl.map((row) => row.name)).toEqual(["1", "2"]);
  expect(wasl.every((row) => row.capacity === 2)).toBe(true);

  expect(parsed.rows.find((row) => row.name === "Room 101")).toMatchObject({
    accommodationType: "good_general",
    capacity: 2,
  });
  const ebpv = parsed.rows.find((row) => row.name === "Apartment 1");
  expect(ebpv).toMatchObject({ accommodationType: "ebpv", capacity: 4 });
  // No gender is imported — staff do gender and assignment manually.
  expect(ebpv).not.toHaveProperty("gender");

  // 2. Preview against the Phase 1 corrected pools.
  const preview = await t.query(api.agcRoomAssignments.previewRoomImport, {
    sessionToken: token,
    rows: parsed.rows,
  });
  const hostelPreview = preview.find((entry) => entry.accommodationType === "hostel");
  expect(hostelPreview?.withinPool).toBe(true);
  expect(hostelPreview?.poolTotal).toBe(8);
  // Two EBPV apartments want 4 + 5 = 9 but the pool is 8 → over the pool.
  const ebpvPreview = preview.find((entry) => entry.accommodationType === "ebpv");
  expect(ebpvPreview?.withinPool).toBe(false);
  expect(ebpvPreview?.poolTotal).toBe(8);

  // 3. The apartment-2 row (5 delegates) fails the commit…
  await expect(() =>
    t.mutation(api.agcRoomAssignments.importRooms, {
      sessionToken: token,
      rows: parsed.rows,
    }),
  ).rejects.toThrow(/at most 4 delegates/);

  // 4. …so staff drop the bad row and commit the corrected sheet.
  const validRows = parsed.rows.filter((row) => row.name !== "Apartment 2");
  const outcome = await t.mutation(api.agcRoomAssignments.importRooms, {
    sessionToken: token,
    rows: validRows,
  });
  expect(outcome.created).toBe(6);
  expect(outcome.updated).toBe(0);

  // Rooms really exist afterwards, ungendered and ready for manual assignment.
  const rooms = await t.query(api.agcRoomAssignments.listRoomsAdmin, {
    sessionToken: token,
  });
  expect(rooms).toHaveLength(6);
  const room101 = rooms.find((room) => room.name === "101");
  expect(room101).toMatchObject({
    accommodationType: "hostel",
    capacity: 4,
    gender: null,
    occupants: 0,
  });
  const apartment = rooms.find((room) => room.name === "Apartment 1");
  expect(apartment).toMatchObject({ accommodationType: "ebpv", capacity: 4, gender: null });

  // 5. Re-importing the same sheet updates in place instead of duplicating.
  const reImport = await t.mutation(api.agcRoomAssignments.importRooms, {
    sessionToken: token,
    rows: validRows,
  });
  expect(reImport.created).toBe(0);
  expect(reImport.updated).toBe(6);
  const roomsAfter = await t.query(api.agcRoomAssignments.listRoomsAdmin, {
    sessionToken: token,
  });
  expect(roomsAfter).toHaveLength(6);
});
